# The medium-board descent contacted its near edge because the grasp was too far forward.
# I will shift the open hand rearward to center the board between the jaws before retrying.
obs, stopped = move_ee('left', [-0.005,-0.29,0.99], qy, 1, max_steps=10, speed=0.012)
if not stopped:
    obs, stopped = move_ee('left', [-0.005,-0.29,0.924], qy, 1, max_steps=10, speed=0.01)
if not stopped:
    obs, stopped = move_ee('left', [-0.005,-0.29,0.924], qy, 0, max_steps=6)
if not stopped:
    obs, stopped = move_ee('left', [-0.005,-0.29,1.075], qy, 0, max_steps=14, speed=0.018)
print('medium_revised_grasp_stopped', stopped)

