# The clear view reveals a displaced middle support and crossed boards, so adding the top pieces would be unstable.
# I will lift the medium board away to expose the supports and recover the best stable assembly within the remaining budget.
obs, stopped = move_ee('left', [-0.02,-0.195,1.105], qboard, 1, max_steps=18, speed=0.023)
if not stopped:
    obs, stopped = move_ee('left', [-0.02,-0.195,1.02], qboard, 1, max_steps=10, speed=0.015)
if not stopped:
    obs, stopped = move_ee('left', [-0.02,-0.195,1.02], qboard, 0, max_steps=6)
if not stopped:
    obs, stopped = move_ee('left', [-0.02,-0.195,1.13], qboard, 0, max_steps=11, speed=0.02)
print('recovery_lift_stopped', stopped)

